 private Orion_Conversation_Service $conversations;private Orion_Rate_Limiter $rate_limiter;private Orion_Knowledge_Base $knowledge;private Orion_Semantic_Product_Planner $planner;private Orion_Intent_Classifier $classifier;private Orion_Context_Manager $context;private Orion_Manager_Handoff $handoff;private Orion_AI_Trace_Service $traces;private int $trace_id=0;private float $started=0;
 public function __construct(Orion_Conversation_Service $c,Orion_Rate_Limiter $r,Orion_Knowledge_Base $k,Orion_Semantic_Product_Planner $p,Orion_Intent_Classifier $i,Orion_Context_Manager $x,Orion_Manager_Handoff $h,Orion_AI_Trace_Service $t){$this->conversations=$c;$this->rate_limiter=$r;$this->knowledge=$k;$this->planner=$p;$this->classifier=$i;$this->context=$x;$this->handoff=$h;$this->traces=$t;}
 public function respond(string $message,string $session_key=''):array|WP_Error{$this->started=microtime(true);$message=trim(sanitize_textarea_field($message));if($message===''||mb_strlen($message)>1200)return new WP_Error('invalid_message','Please enter a message of up to 1,200 characters.',array('status'=>400));$settings=Orion_AI_Settings::get();if($settings['enabled']!=='1')return new WP_Error('disabled','The assistant is currently unavailable.',array('status'=>503));$rate=$this->rate_limiter->check($settings);if(is_wp_error($rate))return$rate;$conversation=$this->conversations->resolve($session_key,$settings);if(is_wp_error($conversation))return$conversation;$id=(int)$conversation['id'];$this->trace_id=$this->traces->begin($id,$message,$settings);$history=$this->conversations->history($id);$this->conversations->save_user_message($id,$message);$state=$this->conversations->state($id);$classification=$this->classifier->classify($message,$history,$state,$settings);$this->traces->update($this->trace_id,array('intent'=>$classification['intent'],'topic'=>$classification['topic'],'stages'=>array('classification'=>$classification)));$diagnostic=(string)($classification['_diagnostic']['status']??'');if(in_array($diagnostic,array('provider_error','invalid_output'),true)){$stage=$diagnostic==='provider_error'?'classification_provider_error':'classification_invalid_output';$reason=(string)($classification['_diagnostic']['error']??'The AI provider returned no valid routing response.');$this->create_gap($id,$message,array('trace_id'=>$this->trace_id,'reason'=>$reason,'failure_stage'=>$stage,'classification'=>$classification,'state'=>$state));$this->traces->complete($this->trace_id,'failed',$stage,$reason,$this->elapsed());return new WP_Error('ai_temporarily_unavailable','The AI service is temporarily unavailable. Please try again.',array('status'=>503,'trace_id'=>$this->trace_id));}$state=$this->context->apply($state,$classification);$this->conversations->save_state($id,$state);$this->traces->update($this->trace_id,array('stages'=>array('context'=>array('saved_state'=>$state))));$this->conversations->record_event('intent_classified',array('intent'=>$classification['intent'],'topic'=>$classification['topic'],'confidence'=>$classification['confidence']),$id);if(!empty($classification['needs_clarification'])&&!empty($classification['clarifying_questions']))return$this->finish($conversation,$settings,'I need a little more information before I can give you a reliable answer.',array(),array(),array(),'clarification_requested',$classification['clarifying_questions'],'clarification');return match($classification['intent']){'store_policy'=>$this->policy($conversation,$settings,$message,$classification,$state),'project_recommendation','product_search'=>$this->products($conversation,$settings,$message,$classification,$state),'manager_follow_up'=>$this->refer($conversation,$settings,$message,$classification,$state,'This request cannot yet be confirmed from the available evidence.','classifier_requested_review'),default=>$this->general($conversation,$settings,$message,$history,$state)};}
 private function policy(array $conversation,array $settings,string $message,array $classification,array $state):array|WP_Error{$query=$classification['policy_query']?:$message;$docs=$this->knowledge->relevant($query,5);$this->traces->update($this->trace_id,array('stages'=>array('knowledge'=>array('query'=>$query,'result_count'=>count($docs),'sources'=>array_values(array_unique(array_filter(array_column($docs,'source_url'))))))));if(!$docs)return$this->refer($conversation,$settings,$message,$classification,$state,'I do not have confirmed information about that in the store knowledge base.','knowledge_no_results');$provider=Orion_AI_Provider_Factory::create($settings);$prompt='Answer only from supplied store knowledge. Break the customer question into every independently requested factual requirement, including requested conditions, exact values, prices, dates, durations and guarantees. Return JSON only: {"supported":false,"answer":"","requirements":[{"requirement":"...","supported":false,"evidence":""}]}. Include every requirement. Mark a requirement supported only when evidence is a short verbatim quote from the supplied documents that explicitly answers it. Overall supported may be true only when every requirement is supported. If any requirement is unsupported, set overall supported false and answer to an empty string; never provide a partial answer. A statement that a charge exists does not support its exact amount. Never infer delivery areas, prices, dates, policies or guarantees.';$result=$provider->chat(array(array('role'=>'system','content'=>$prompt),array('role'=>'user','content'=>wp_json_encode(array('question'=>$message,'documents'=>$docs)))));$data=!empty($result['ok'])?$this->decode((string)($result['message']['content']??'')):null;$assessment=Orion_Policy_Evidence::assess($data,$docs);$this->traces->update($this->trace_id,array('stages'=>array('policy_validation'=>array('provider_ok'=>!empty($result['ok']),'supported'=>$assessment['supported'],'requirements'=>$assessment['requirements'],'unsupported_requirements'=>$assessment['unsupported_requirements'],'usage'=>$result['usage']??array(),'attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])))));if(!$assessment['supported'])return$this->refer($conversation,$settings,$message,$classification,$state,'The available store information does not explicitly answer every part of that question.','knowledge_not_supported');return$this->finish($conversation,$settings,sanitize_textarea_field((string)$assessment['answer']),array(),$this->sources($docs),$result['usage']??array(),'policy_answered');}
 private function products(array $conversation,array $settings,string $message,array $classification,array $state):array|WP_Error{$kit=$this->planner->recommend($classification,$state,$settings);$required_missing=array();foreach($kit['plan']as$group)if(!empty($group['required'])&&in_array($group['role'],$kit['missing_roles'],true))$required_missing[]=$group['role'];$this->traces->update($this->trace_id,array('stages'=>array('catalogue'=>array('roles'=>array_column($kit['plan'],'role'),'candidate_counts'=>array_map(static fn($g)=>count($g['candidates']??array()),$kit['plan']),'candidate_summaries'=>array_map(static fn($g)=>array('role'=>$g['role']??'','items'=>array_map(static fn($c)=>array('id'=>$c['id']??0,'name'=>$c['name']??'','retrieval'=>$c['retrieval']??array()),$g['candidates']??array())),$kit['plan']),'selected'=>array_map(static fn($p)=>array('id'=>$p['id'],'role'=>$p['kit_role']??'','need_key'=>$p['need_key']??'','recommendation_reason'=>$p['recommendation_reason']??'','selection_evidence'=>$p['selection_evidence']??array()),$kit['products']),'missing_roles'=>$kit['missing_roles'],'conditional_roles'=>$kit['conditional_roles']??array(),'selection_diagnostic'=>$kit['diagnostic']??array(),'required_missing'=>$required_missing))));if(!$kit['products']||$required_missing)return$this->refer($conversation,$settings,$message,$classification,array_merge($state,array('missing_roles'=>$required_missing?:$kit['missing_roles'])),'I could not find enough confirmed suitable products in the live catalogue.',$kit['products']?'required_product_missing':'catalogue_no_candidates',$kit['products']);$provider=Orion_AI_Provider_Factory::create($settings);$prompt='Write a concise shopping answer using only verified live products. Explain each selected product role. State every non-empty selection_evidence uncertainty clearly and never turn it into a positive compatibility claim. Never invent suitability, compatibility, quantity, coverage, price, stock or links. A product volume or pack size alone does not prove that it is the right quantity for the project area. State quantity or coverage only when explicit numeric manufacturer coverage is present in verified_products; otherwise tell the customer to check the product instructions and do not call the pack size appropriate for the area. Never cite the recommendation itself as evidence. Present missing application tools briefly. conditional_roles are deferred preparation items, not missing products: explain briefly that they may be needed only when surface condition requires them. Never imply that every optional role is required. Follow the supplied product order, which is already prioritised for visible cards.';$result=$provider->chat(array(array('role'=>'system','content'=>$prompt),array('role'=>'user','content'=>wp_json_encode(array('request'=>$message,'state'=>$state,'verified_products'=>$kit['products'],'missing_roles'=>$kit['missing_roles'],'conditional_roles'=>$kit['conditional_roles']??array())))));$this->traces->update($this->trace_id,array('stages'=>array('answer_generation'=>array('attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])))));$answer=!empty($result['ok'])?trim((string)($result['message']['content']??'')):'';if($answer==='')$answer='I found verified products for this request. Please review the product cards and manufacturer instructions.';return$this->finish($conversation,$settings,$answer,$kit['products'],array(),$result['usage']??array(),'project_recommendation_completed');}
 private function general(array $conversation,array $settings,string $message,array $history,array $state):array|WP_Error{$provider=Orion_AI_Provider_Factory::create($settings);$system=$settings['system_prompt'].' Do not invent store-specific facts, product availability, policies or prices.';$messages=array(array('role'=>'system','content'=>$system));foreach(array_slice($history,-8)as$item)$messages[]=array('role'=>$item['role'],'content'=>$item['content']);$messages[]=array('role'=>'user','content'=>$message);$result=$provider->chat($messages);$this->traces->update($this->trace_id,array('stages'=>array('answer_generation'=>array('attempts'=>$result['attempts']??array(),'fallback_used'=>!empty($result['fallback_used'])))));if(empty($result['ok'])){$reason=(string)($result['error']??'Provider error');$this->create_gap((int)$conversation['id'],$message,array('trace_id'=>$this->trace_id,'reason'=>$reason,'failure_stage'=>'answer_provider_error','state'=>$state));$this->traces->complete($this->trace_id,'failed','answer_provider_error',$reason,$this->elapsed());return new WP_Error('ai_error',$reason,array('status'=>502));}$answer=trim((string)($result['message']['content']??''))?:'I could not prepare a reliable answer.';return$this->finish($conversation,$settings,$answer,array(),array(),$result['usage']??array(),'general_answered');}
 private function refer(array $conversation,array $settings,string $message,array $classification,array $state,string $reason,string $stage,array $products=array()):array|WP_Error{$id=$this->create_gap((int)$conversation['id'],$message,array('trace_id'=>$this->trace_id,'reason'=>$reason,'failure_stage'=>$stage,'classification'=>$classification,'state'=>$state));$this->traces->update($this->trace_id,array('stages'=>array('knowledge_gap'=>array('gap_id'=>$id,'reason'=>$reason))));$answer=$reason.' This unanswered request has been recorded for review'.($id?' as reference #'.$id:'').'.';return$this->finish($conversation,$settings,$answer,$products,array(),array(),'knowledge_gap_recorded',array(),'knowledge_gap',$stage,$reason);}
 private function create_gap(int $conversation_id,string $question,array $context):int{$id=$this->handoff->create($conversation_id,$question,$context);$this->conversations->record_event('knowledge_gap_created',array('gap_id'=>$id,'trace_id'=>$this->trace_id,'reason_code'=>$context['failure_stage']??'unanswered'),$conversation_id);return$id;}
 private function finish(array $conversation,array $settings,string $answer,array $products,array $sources,array $usage,string $event,array $questions=array(),string $trace_status='completed',string $failure_stage='',string $failure_reason=''):array|WP_Error{$id=(int)$conversation['id'];$limit=(int)$settings['questions_per_session'];if(!$this->conversations->increment($id,$limit)){$this->traces->complete($this->trace_id,'failed','session_limit','Question limit reached',$this->elapsed());return new WP_Error('session_limit','This chat session has ended.',array('status'=>429));}$saved=$answer;if($questions)$saved.="\n".implode("\n",array_map(static fn($q)=>'- '.$q,$questions));$this->conversations->save_assistant_message($id,$saved,$usage);$this->conversations->record_event($event,array('products'=>count($products),'trace_id'=>$this->trace_id),$id);$this->traces->complete($this->trace_id,$trace_status,$failure_stage,$failure_reason,$this->elapsed(),array('stages'=>array('response'=>array('event'=>$event,'product_count'=>count($products),'usage'=>$usage,'clarifying_questions'=>$questions))));return array('answer'=>$answer,'message'=>$answer,'questions'=>$questions,'products'=>$this->unique_products($products),'estimate'=>null,'sources'=>$sources,'actions'=>$products?array(array('type'=>'add_to_cart','label'=>'Add available products individually')):array(),'remaining'=>max(0,$limit-((int)$conversation['question_count']+1)),'sessionLimit'=>$limit,'session'=>(string)$conversation['session_key'],'traceId'=>$this->trace_id);}
 private function elapsed():int{return(int)round((microtime(true)-$this->started)*1000);}private function decode(string $text):?array{$text=trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',trim($text)));$data=json_decode($text,true);if(is_array($data))return$data;if(preg_match('/\{[\s\S]*\}/',$text,$m)){$data=json_decode($m[0],true);return is_array($data)?$data:null;}return null;}private function sources(array $docs):array{$out=array();foreach($docs as$d)if(!empty($d['source_url']))$out[$d['source_url']]=array('title'=>$d['title'],'url'=>$d['source_url']);return array_values($out);}private function unique_products(array $products):array{$out=array();foreach($products as$p)if(!empty($p['id']))$out[(int)$p['id']]=$p;return array_values($out);}
}
